#![cfg_attr(all(test, coverage_nightly), feature(coverage_attribute))]

use std::fmt;
use std::str::FromStr;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// A journal entry's unique identifier. Generated by the frontend on entry
/// creation; the backend only stores and looks entries up by it.
///
/// ts-rs warns that it cannot parse `#[serde(transparent)]`. That is benign
/// here: its default handling of a single-field tuple struct already emits
/// the inner type, so `Id.ts` is `string` either way. The warning is left
/// on rather than silenced with ts-rs's `no-serde-warnings`, which would
/// also hide a genuinely dropped `rename`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(transparent)]
pub struct Id(Uuid);

impl Id {
    pub fn new() -> Self {
        Self(Uuid::new_v4())
    }
}

impl Default for Id {
    fn default() -> Self {
        Self::new()
    }
}

impl fmt::Display for Id {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(&self.0, f)
    }
}

impl FromStr for Id {
    type Err = uuid::Error;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Ok(Self(Uuid::from_str(s)?))
    }
}

/// Identifies one media item (an image, later audio) owned by an entry. The
/// frontend generates it; a media blob is named `<entry-id>.media-<media-id>`.
///
/// Same shape as [`Id`], and the same benign ts-rs `transparent` warning.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(transparent)]
pub struct MediaId(Uuid);

impl MediaId {
    pub fn new() -> Self {
        Self(Uuid::new_v4())
    }
}

impl Default for MediaId {
    fn default() -> Self {
        Self::new()
    }
}

impl fmt::Display for MediaId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(&self.0, f)
    }
}

impl FromStr for MediaId {
    type Err = uuid::Error;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Ok(Self(Uuid::from_str(s)?))
    }
}

/// What a media item is, stored next to its bytes. One variant per kind, each
/// carrying only the fields that make sense for it. There is deliberately no
/// SVG format: SVG is a document that can carry script, so it is left
/// unrepresentable.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum MediaMeta {
    /// Decoded, orientation-applied pixel dimensions; both non-zero.
    Image {
        format: ImageFormat,
        width: u32,
        height: u32,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(rename_all = "snake_case")]
pub enum ImageFormat {
    Webp,
    Jpeg,
    Png,
    Gif,
    Heic,
    Avif,
    Tiff,
}

/// Which of an image's up to three blobs. The original is the user's file;
/// the display copy exists only when the original is not web-safe; the
/// thumbnail is what an entry's read view shows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(rename_all = "snake_case")]
pub enum MediaVariant {
    Original,
    Display,
    Thumb,
}

const HEIC_BRANDS: [&[u8; 4]; 8] = [
    b"heic", b"heix", b"hevc", b"hevx", b"heim", b"heis", b"hevm", b"hevs",
];

impl ImageFormat {
    pub fn mime(self) -> &'static str {
        match self {
            Self::Webp => "image/webp",
            Self::Jpeg => "image/jpeg",
            Self::Png => "image/png",
            Self::Gif => "image/gif",
            Self::Heic => "image/heic",
            Self::Avif => "image/avif",
            Self::Tiff => "image/tiff",
        }
    }

    /// The file extension the plaintext export uses.
    pub fn extension(self) -> &'static str {
        match self {
            Self::Webp => "webp",
            Self::Jpeg => "jpg",
            Self::Png => "png",
            Self::Gif => "gif",
            Self::Heic => "heic",
            Self::Avif => "avif",
            Self::Tiff => "tif",
        }
    }

    /// Whether every webview the app ships in can display it. AVIF is "no"
    /// because WebKitGTK support depends on how it was built.
    pub fn is_web_safe(self) -> bool {
        match self {
            Self::Webp | Self::Jpeg | Self::Png | Self::Gif => true,
            Self::Heic | Self::Avif | Self::Tiff => false,
        }
    }

    /// The format the bytes are, judged by their header alone (never by a
    /// file name or MIME type). `None` for anything else, SVG included.
    /// Mirrored by `sniffImageFormat` in `src/media/format.ts`.
    pub fn sniff(bytes: &[u8]) -> Option<Self> {
        if bytes.starts_with(&[0xFF, 0xD8, 0xFF]) {
            return Some(Self::Jpeg);
        }
        if bytes.starts_with(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A]) {
            return Some(Self::Png);
        }
        if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
            return Some(Self::Gif);
        }
        if bytes.len() >= 12 && &bytes[..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
            return Some(Self::Webp);
        }
        if bytes.starts_with(&[b'I', b'I', b'*', 0]) || bytes.starts_with(&[b'M', b'M', 0, b'*']) {
            return Some(Self::Tiff);
        }
        if bytes.len() >= 12 && &bytes[4..8] == b"ftyp" {
            let brand = &bytes[8..12];
            if brand == b"avif" || brand == b"avis" {
                return Some(Self::Avif);
            }
            if HEIC_BRANDS.iter().any(|b| brand == &b[..]) {
                return Some(Self::Heic);
            }
            if brand == b"mif1" || brand == b"msf1" {
                let size = u32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]) as usize;
                let end = size.min(bytes.len());
                // Compatible brands follow the major brand and its version.
                let brands: Vec<&[u8]> = bytes
                    .get(16..end)
                    .unwrap_or_default()
                    .chunks_exact(4)
                    .collect();
                if brands.iter().any(|b| *b == b"avif" || *b == b"avis") {
                    return Some(Self::Avif);
                }
                if brands
                    .iter()
                    .any(|b| HEIC_BRANDS.iter().any(|h| *b == &h[..]))
                {
                    return Some(Self::Heic);
                }
            }
        }
        None
    }
}

#[derive(Debug, Clone, Serialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(rename_all = "snake_case")]
pub struct Header {
    pub id: Id,
    pub title: String,
    /// When the entry was last written. The list does not sort by this.
    pub updated_at: DateTime<Utc>,
    // Doc comments on these fields reach `src/bindings/` verbatim, so the
    // reasoning stays here where ts-rs will not copy it.
    //
    // `entry_date` is the moment the entry is *about*, and is what the list
    // sorts and groups by. Fixing a typo in a three-month-old entry moves
    // `updated_at` and leaves this alone, so the entry keeps its place in the
    // journal's chronology.
    //
    // An entry written before this field existed has no value on disk and
    // takes its `updated_at`; see the `Deserialize` implementation below.
    // The entry's next save writes the field for good.
    /// The day the entry is about, which is what the journal sorts by.
    pub entry_date: DateTime<Utc>,
}

impl<'de> Deserialize<'de> for Header {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        struct WireHeader {
            id: Id,
            title: String,
            updated_at: DateTime<Utc>,
            #[serde(default)]
            entry_date: Option<DateTime<Utc>>,
        }

        let wire = WireHeader::deserialize(deserializer)?;
        Ok(Self {
            id: wire.id,
            title: wire.title,
            updated_at: wire.updated_at,
            entry_date: wire.entry_date.unwrap_or(wire.updated_at),
        })
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
pub struct Entry {
    #[serde(flatten)]
    pub header: Header,
    pub markdown: String,
}

/// One entry a search matched, as the result row shows it.
///
/// A [`Header`] rather than an [`Entry`]: a result list that carried every
/// matched entry's markdown would hand the frontend the plaintext of the whole
/// journal for a one-letter query. The snippet is the only body text that
/// crosses the bridge, and opening a result goes through `get_entry` like any
/// other row.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[cfg_attr(
    feature = "ts",
    derive(ts_rs::TS),
    ts(export, export_to = "../../../src/bindings/")
)]
#[serde(rename_all = "snake_case")]
pub struct SearchMatch {
    pub header: Header,
    /// A window of the entry around the first match, whitespace collapsed so
    /// it renders as one line. Empty for an entry matched on its title alone
    /// with nothing written in it yet.
    pub snippet: String,
}

#[cfg(test)]
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use super::*;

    /// Mirrors what the frontend sends over `invoke`. Keep this literal
    /// hand-written: building it from the Rust type would only test serde
    /// against itself, and this is the runtime counterpart to the
    /// compile-time guarantee `src/bindings/` gives.
    #[test]
    fn frontend_json_deserializes_into_entry() {
        let json = r##"{"id":"5c1f7c9e-6e8b-4a2f-9c1a-1f6b9b6b0a01","title":"t",
                       "updated_at":"2026-09-07T20:17:50Z",
                       "entry_date":"2026-06-01T09:00:00Z","markdown":"# h"}"##;

        let entry: Entry = serde_json::from_str(json).unwrap();

        assert_eq!(entry.header.title, "t");
        assert_eq!(entry.markdown, "# h");
        assert_eq!(
            entry.header.entry_date,
            "2026-06-01T09:00:00Z".parse::<DateTime<Utc>>().unwrap()
        );
    }

    /// An entry blob written before `entry_date` existed uses its stable
    /// `updated_at`, rather than appearing to move to "now" on every read.
    #[test]
    fn entry_without_entry_date_uses_updated_at() {
        let json = r##"{"id":"5c1f7c9e-6e8b-4a2f-9c1a-1f6b9b6b0a01","title":"t",
                       "updated_at":"2026-09-07T20:17:50Z","markdown":"# h"}"##;

        let entry: Entry = serde_json::from_str(json).unwrap();

        assert_eq!(entry.header.entry_date, entry.header.updated_at);
    }

    /// The `list_entries`/`get_entry` direction. Rust names the wire
    /// format and the generated bindings follow, so the assertion is that
    /// the field keeps its Rust spelling.
    #[test]
    fn header_serializes_snake_case_keys() {
        let header = Header {
            id: "5c1f7c9e-6e8b-4a2f-9c1a-1f6b9b6b0a01".parse().unwrap(),
            title: "t".to_string(),
            updated_at: "2026-09-07T20:17:50Z".parse().unwrap(),
            entry_date: "2026-06-01T09:00:00Z".parse().unwrap(),
        };

        let value = serde_json::to_value(&header).unwrap();

        assert!(value.get("updated_at").and_then(|v| v.as_str()).is_some());
        assert!(value.get("updatedAt").is_none());
        assert!(value.get("entry_date").and_then(|v| v.as_str()).is_some());
        assert!(value.get("entryDate").is_none());
    }

    #[test]
    fn image_meta_serializes_tagged() {
        let meta = MediaMeta::Image {
            format: ImageFormat::Webp,
            width: 20,
            height: 10,
        };
        assert_eq!(
            serde_json::to_string(&meta).unwrap(),
            r#"{"kind":"image","format":"webp","width":20,"height":10}"#
        );
        let back: MediaMeta = serde_json::from_str(&serde_json::to_string(&meta).unwrap()).unwrap();
        assert_eq!(back, meta);
    }

    #[test]
    fn unknown_kinds_formats_and_missing_fields_are_refused() {
        for bad in [
            r#"{"kind":"audio","format":"mp3","duration_ms":1}"#,
            r#"{"kind":"image","format":"svg","width":1,"height":1}"#,
            r#"{"kind":"image","format":"webp","height":1}"#,
        ] {
            assert!(serde_json::from_str::<MediaMeta>(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn image_format_mime_and_extension() {
        let all = [
            (ImageFormat::Webp, "image/webp", "webp"),
            (ImageFormat::Jpeg, "image/jpeg", "jpg"),
            (ImageFormat::Png, "image/png", "png"),
            (ImageFormat::Gif, "image/gif", "gif"),
            (ImageFormat::Heic, "image/heic", "heic"),
            (ImageFormat::Avif, "image/avif", "avif"),
            (ImageFormat::Tiff, "image/tiff", "tif"),
        ];
        for (format, mime, ext) in all {
            assert_eq!(format.mime(), mime);
            assert_eq!(format.extension(), ext);
            assert_eq!(
                format.is_web_safe(),
                !matches!(
                    format,
                    ImageFormat::Heic | ImageFormat::Avif | ImageFormat::Tiff
                )
            );
        }
    }

    fn ftyp(major: &[u8; 4], compatible: &[&[u8; 4]]) -> Vec<u8> {
        let size = 16 + 4 * compatible.len();
        let mut v = (size as u32).to_be_bytes().to_vec();
        v.extend_from_slice(b"ftyp");
        v.extend_from_slice(major);
        v.extend_from_slice(&[0; 4]);
        for c in compatible {
            v.extend_from_slice(*c);
        }
        v
    }

    #[test]
    fn sniff_recognises_each_format_from_its_header() {
        let webp = [b"RIFF".as_slice(), &[0; 4], b"WEBPVP8 "].concat();
        let cases: [(Vec<u8>, Option<ImageFormat>); 14] = [
            (vec![0xFF, 0xD8, 0xFF, 0xE0], Some(ImageFormat::Jpeg)),
            (
                vec![0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A, 0],
                Some(ImageFormat::Png),
            ),
            (b"GIF87a..".to_vec(), Some(ImageFormat::Gif)),
            (b"GIF89a..".to_vec(), Some(ImageFormat::Gif)),
            (webp, Some(ImageFormat::Webp)),
            (vec![b'I', b'I', b'*', 0, 8], Some(ImageFormat::Tiff)),
            (vec![b'M', b'M', 0, b'*', 8], Some(ImageFormat::Tiff)),
            (ftyp(b"avif", &[]), Some(ImageFormat::Avif)),
            (ftyp(b"heic", &[]), Some(ImageFormat::Heic)),
            (ftyp(b"mif1", &[b"miaf", b"avif"]), Some(ImageFormat::Avif)),
            (ftyp(b"mif1", &[b"miaf", b"heic"]), Some(ImageFormat::Heic)),
            (ftyp(b"mif1", &[b"miaf"]), None),
            (ftyp(b"mp42", &[b"heic"]), None),
            (
                b"<svg xmlns=\"http://www.w3.org/2000/svg\"/>".to_vec(),
                None,
            ),
        ];
        for (bytes, want) in cases {
            assert_eq!(ImageFormat::sniff(&bytes), want, "{bytes:?}");
        }
        assert_eq!(ImageFormat::sniff(&[]), None);
    }

    #[test]
    fn sniff_survives_truncated_and_oversized_ftyp_boxes() {
        // Cut off inside the major brand.
        assert_eq!(ImageFormat::sniff(&ftyp(b"mif1", &[])[..10]), None);
        // The box claims more bytes than exist: read only what is there.
        let mut v = ftyp(b"mif1", &[b"heic"]);
        v[..4].copy_from_slice(&u32::MAX.to_be_bytes());
        assert_eq!(ImageFormat::sniff(&v), Some(ImageFormat::Heic));
        // A box smaller than its own header has no compatible brands.
        let mut v = ftyp(b"mif1", &[b"heic"]);
        v[..4].copy_from_slice(&4u32.to_be_bytes());
        assert_eq!(ImageFormat::sniff(&v), None);
    }

    #[test]
    fn media_variant_serde_uses_snake_case() {
        for (variant, text) in [
            (MediaVariant::Original, "\"original\""),
            (MediaVariant::Display, "\"display\""),
            (MediaVariant::Thumb, "\"thumb\""),
        ] {
            assert_eq!(serde_json::to_string(&variant).unwrap(), text);
            assert_eq!(serde_json::from_str::<MediaVariant>(text).unwrap(), variant);
        }
        assert!(serde_json::from_str::<MediaVariant>("\"full\"").is_err());
        assert!(serde_json::from_str::<ImageFormat>("\"heic\"").is_ok());
        assert!(serde_json::from_str::<ImageFormat>("\"svg\"").is_err());
    }

    #[test]
    fn media_id_round_trips_through_display() {
        let id = MediaId::new();
        assert_eq!(id.to_string().parse::<MediaId>().unwrap(), id);
    }

    #[test]
    fn default_ids_are_fresh_and_distinct() {
        assert_ne!(Id::default(), Id::default());
        assert_ne!(MediaId::default(), MediaId::default());
    }
}
